function toggleMenu(){document.getElementById("nav-menu").classList.toggle("active"),document.querySelector(".overlay").classList.toggle("active")}function calcularPiso(){const e=parseFloat(document.getElementById("comprimento").value),t=parseFloat(document.getElementById("largura").value),a=parseFloat(document.getElementById("piso-largura").value)/100,o=parseFloat(document.getElementById("piso-altura").value)/100,l=parseFloat(document.getElementById("conteudo-caixa").value),n=parseFloat(document.getElementById("residuo").value),c=document.getElementById("resultado-area");if(isNaN(e)||isNaN(t)||isNaN(a)||isNaN(o)||isNaN(l))return void alert("Por favor, preencha todos os campos corretamente.");const s=e*t,d=s*(1+n),i=a*o,r=Math.ceil(d/i),u=Math.ceil(d/l);c.style.display="block",document.getElementById("area-total").textContent=s.toFixed(2),document.getElementById("pecas-total").textContent=r,document.getElementById("caixas-total").textContent=u,window.innerWidth<600&&c.scrollIntoView({behavior:"smooth",block:"start"}),"function"==typeof window.salvarCalculo&&window.salvarCalculo("Calculadora de Piso",`Ambiente: ${e}x${t}m | Piso: ${100*a}x${100*o}cm`,`Área: ${s.toFixed(2)}m² | Peças: ${r} | Caixas: ${u}`)}